const OPS_KEY='ngyn-operations-v1';
const timeLabel=d=>new Date(d).toLocaleString('en-CA',{timeZone:'America/Halifax',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const nowISO=()=>new Date().toISOString();
const commonSizes=[['Square',1080,1080],['Portrait',1080,1350],['Tall portrait',1080,1440],['Story / vertical',1080,1920],['Landscape',1200,630],['Widescreen',1920,1080]];
const initialCases=Array.from({length:80},(_,i)=>({id:'CASE-'+(2100+i),channel:assetsData.channels[i%assetsData.channels.length].id,type:i%3?'Comment':'Message',text:['Water is collecting at the Alder Street underpass. Is the road closed?','Can you confirm the accessible stop for Route 8 during the detour?','The new park trail is wonderful. Thank you!','Our green bin was missed again. How can we report it?','What time does registration open for swimming lessons?'][i%5],author:['Resident A','Resident B','Resident C','Resident D','Resident E'][i%5]+' · fictional',sentiment:['Negative','Concerned','Positive','Negative','Neutral'][i%5],urgency:i===0?'Critical':i%7===0?'High':'Normal',owner:i%4?accessUsers[(i+2)%accessUsers.length].id:'',status:i>55?'Resolved':'Open',notes:[],draft:'',created:nowISO()}));
const initialPosts=Array.from({length:42},(_,i)=>({id:'POST-'+(300+i),channel:assetsData.channels[i%assetsData.channels.length].id,title:['Fall leaf collection','Route 8 detour','Explore the waterfront','Council meeting recap','Community swim registration','Stormwater service notice'][i%6],text:['Fall leaf collection begins Monday. Place paper yard-waste bags at the curb by 7 a.m. Find your collection day on the municipal service calendar.','Route 8 is using a temporary detour. Accessible boarding is available at the temporary Alder Street stop. Check your trip before travelling.','A little fresh air, close to home. Discover accessible trails and enjoy autumn along the Harbourview waterfront.','Your council, your community. Read the highlights from this week’s meeting and learn about upcoming opportunities to participate.','Make a splash this season. Community swim registration opens Friday at 9 a.m. Accessible programs and fee assistance are available.','Crews are checking storm drains following heavy rainfall. Avoid flooded roads and report service concerns through the municipal contact centre.'][i%6],status:['Draft','In review','Scheduled','Published','Failed'][i%5],art:i%6,created:nowISO(),alt:'Fictional municipal illustration for the service update.',scheduled:'2026-11-02T10:30',history:[]}));
let ops;try{ops=JSON.parse(localStorage.getItem(OPS_KEY))||null}catch{}
ops=ops||{cases:initialCases,posts:initialPosts,events:[],paused:false,updateIndex:0,boards:{}};
let currentPage='soc',viewUser='admin',contentNetwork='All',contentStatus='All',contentSearch='',inboxSearch='',inboxSentiment='All',inboxOwner='All',inboxType='All',inboxState='Open',selectedCase=null,streamTimer=null;
let contentLimit=18;
const currentUser=()=>viewUser==='admin'?null:accessUsers.find(u=>u.id===viewUser);
const isAdmin=()=>viewUser==='admin';
const can=f=>isAdmin()||(typeof effectiveFunctionAccess==='function'?effectiveFunctionAccess(currentUser(),f):Boolean(currentUser()?.functions.includes(f)));
const accountAllowed=id=>isAdmin()||(typeof effectiveAccountAccess==='function'?effectiveAccountAccess(currentUser(),id):Boolean(currentUser()?.channels.includes(id)));
const channelById=id=>assetsData.channels.find(c=>c.id===id);
const visibleCases=()=>ops.cases.filter(c=>accountAllowed(c.channel)&&(isAdmin()||hasAccountFunction(currentUser(),'inbox.respond','channels',c.channel)));
const visiblePosts=()=>ops.posts.filter(p=>accountAllowed(p.channel));
function saveOps(){try{localStorage.setItem(OPS_KEY,JSON.stringify(ops));return true}catch{toast('Demo storage is full. Changes could not be saved.');return false}}
function logOps(action,detail){ops.events.unshift({id:crypto.randomUUID(),action,detail,actor:isAdmin()?'Demo administrator':currentUser()?.name,time:nowISO()});ops.events=ops.events.slice(0,100);saveOps()}
function preferenceKey(){return 'ngyn-preferences-'+(viewUser==='admin'?'administrator':viewUser)}
function getPreferences(){try{return JSON.parse(localStorage.getItem(preferenceKey()))||{theme:'dark',size:'standard',contrast:false,motion:false,focus:true}}catch{return {theme:'dark',size:'standard',contrast:false,motion:false,focus:true}}}
function applyPreferences(){const p=getPreferences();document.documentElement.dataset.theme=p.theme;document.documentElement.dataset.textSize=p.size;document.documentElement.classList.toggle('high-contrast',p.contrast);document.documentElement.classList.toggle('reduce-motion',p.motion);document.documentElement.classList.toggle('strong-focus',p.focus)}
const navSections=[['WORKSPACE',[['soc','Social Operation Center','◎',null]]],['CONTENT',[['content','All content','▦','content.create'],['assets','Asset groups','▱','content.create'],['calendar','Publishing calendar','▦','content.publish']]],['ENGAGEMENT',[['inbox','Inbox & comments','☷','inbox.respond'],['listening','Social listening','◉','reports.view']]],['INSIGHTS',[['analytics','Analytics & reports','▥','reports.view'],['ads','Advertising','◇','ads.create']]],['ADMINISTRATION',[['users','Users & access','♙','admin'],['audit','Activity log','≡','admin']]]];
function pageAllowed(page){if(page==='preferences'||page==='soc')return true;if(['users','audit'].includes(page))return isAdmin();if(page==='assets')return isAdmin();if(page==='content')return ['content.create','content.approve','content.publish','reports.view'].some(can);if(page==='calendar')return can('content.publish');if(page==='inbox')return can('inbox.respond');if(page==='ads')return can('ads.create')||can('ads.manage');return can('reports.view')}
function menuMarkup(){return navSections.map(([title,entries])=>{const available=entries.filter(e=>pageAllowed(e[0]));return available.length?`<div class="menu-section"><div class="menu-label">${title}</div>${available.map(e=>`<button data-go="${e[0]}" ${e[0]==='assets'?'id="groups-nav"':e[0]==='users'?'id="users-nav"':''} class="${currentPage===e[0]?'active':''}"><span class="menu-symbol">${e[2]}</span>${e[1]}</button>`).join('')}</div>`:''}).join('')}
function renderWorkspace(page=currentPage){if(!pageAllowed(page)){page='soc';toast('Your demo user does not have that function permission.')}currentPage=page;applyPreferences();document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div><h1>NGYN</h1><small>Harbourview · fictional demo</small></div></div><nav class="nav">${menuMarkup()}</nav><div class="sidebar-preferences"><button class="btn" data-go="preferences">⚙ My preferences</button><small>Simulated APIs · browser demo store</small></div></aside><section class="content"><header class="topbar"><button class="btn mobile-menu" data-cmd="menu" aria-label="Toggle menu">☰</button><div class="crumb"><small>Municipality of Harbourview · Fictional</small><strong>${({soc:'Social Operation Center',content:'All content',assets:'Asset groups',inbox:'Resident inbox & comments',preferences:'My preferences',users:'Users & access',audit:'Activity log'})[page]||page}</strong></div><label class="view-as">View as user<select id="preview-user" aria-label="View as user"><option value="admin">Demo administrator</option>${accessUsers.map(u=>`<option value="${u.id}" ${viewUser===u.id?'selected':''}>${safe(u.name)}</option>`).join('')}</select></label><button class="btn" data-go="preferences" aria-label="My preferences">⚙</button></header><main id="main" class="main"></main></section></div><div id="modal"></div>`;if(page==='assets'){showAssetGroups();decorateBrand()}else if(page==='users'){showUsers()}else if(page==='soc')renderSOC();else if(page==='content'||page==='calendar')renderContent(page==='calendar');else if(page==='inbox')renderInbox();else if(page==='preferences')renderPreferences();else if(page==='audit')renderAudit();else renderSupporting(page);document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>renderWorkspace(b.dataset.go));document.querySelector('#preview-user').onchange=e=>{viewUser=e.target.value;selectedCase=null;renderWorkspace('soc')};document.querySelector('[data-cmd="menu"]')?.addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'));bindOpsCommands()}
function heading(title,description,buttons=''){return `<div class="page-head groups-heading"><div><div class="eyebrow">HARBOURVIEW / DEMO WORKSPACE</div><h2>${title}</h2><p>${description}</p></div><div class="actions">${buttons}</div></div>`}
function emptyAccess(){return '<div class="ops-empty"><h3>No channel access</h3><p>An administrator must assign a channel before you can view its content or resident conversations.</p></div>'}
function renderSOC(){const cases=visibleCases(),open=cases.filter(c=>c.status!=='Resolved'),critical=open.filter(c=>c.urgency==='Critical'),scheduled=visiblePosts().filter(p=>p.status==='Scheduled');document.querySelector('#main').innerHTML=heading('Social Operation Center','What needs action, who owns it, and what changes next.',`<span class="sample-label">SIMULATED UPDATES</span><button class="btn" data-cmd="stream">${streamTimer?'Ⅱ Pause stream':'▶ Play demo stream'}</button><button class="btn primary" data-cmd="next-update">Next update →</button>`)+`<div class="ops-emergency ${critical.length||ops.paused?'critical':''}"><div><span class="eyebrow">${critical.length?'PRIORITY INCIDENT':'PUBLISHING CONTROL'}</span><h3>${critical.length?`${critical.length} critical resident report${critical.length>1?'s':''} need verification`:ops.paused?'Publishing is paused':'No critical resident reports'}</h3><p>${critical.length?'Reported flooding at Alder Street underpass. Verify with municipal operations; sentiment is not evidence of an emergency.':'Monitor incoming reports and assigned cases.'}</p><strong>${ops.paused?`${scheduled.length} scheduled posts blocked by the demo pause`:'Scheduled posts are eligible for manual demo processing'}</strong></div><div class="actions">${can('inbox.respond')?'<button class="btn" data-cmd="critical-case">Open priority case</button>':''}${isAdmin()?`<button class="btn ${ops.paused?'primary':'danger'}" data-cmd="pause-publishing">${ops.paused?'Authorize resume':'Pause publishing'}</button>`:''}</div></div><div class="grid metrics">${[['Open cases',open.length],['Unassigned',open.filter(c=>!c.owner).length],['High priority',open.filter(c=>c.urgency==='High').length],['Scheduled / blocked',scheduled.length]].map(([l,v])=>`<div class="metric"><span class="label">${l}</span><b>${v}</b><span class="delta">Derived from current demo records</span></div>`).join('')}</div>${!isAdmin()&&!assetsData.channels.some(c=>accountAllowed(c.id))?emptyAccess():`<div class="ops-columns"><section class="card"><h3>Response priorities</h3>${open.slice().sort((a,b)=>({Critical:0,High:1,Normal:2}[a.urgency]-{Critical:0,High:1,Normal:2}[b.urgency])).slice(0,5).map(c=>`<button class="ops-list-button" data-case-open="${c.id}"><span><strong>${safe(c.text.slice(0,70))}</strong><small>${c.id} · ${safe(accessUsers.find(u=>u.id===c.owner)?.name||'Unassigned')} · ${c.urgency==='Critical'?'Verify immediately':c.urgency==='High'?'Review within 15 min':'2h demo target'}</small></span><span class="badge ${c.urgency==='Critical'?'fail':'warn'}">${c.urgency}</span></button>`).join('')||'<p>No open cases.</p>'}</section><section class="card"><h3>Publishing queue</h3><p class="ops-muted">${ops.paused?'Pause gate active. Jobs cannot be processed.':'Manual demo processing only. Nothing is transmitted.'}</p>${scheduled.slice(0,4).map(p=>`<div class="row"><div class="grow"><strong>${safe(p.title)}</strong><small>${safe(channelById(p.channel)?.network||'Channel')}</small></div><span class="badge ${ops.paused?'fail':'warn'}">${ops.paused?'Blocked':'Scheduled'}</span></div>`).join('')}${can('content.publish')?'<button class="btn" data-cmd="process-queue">Process next demo job</button>':''}<h3 style="margin-top:25px">Integration signals</h3><p class="ops-muted">Bluesky · sample sync delayed 4 minutes. Other networks: demo snapshots only.</p></section></div>`}<section class="card" style="margin-top:20px"><h3>Live simulation feed</h3><p class="ops-muted">Play advances one fictional event every 12 seconds. Pause anytime. The feed never calls a social API.</p>${(isAdmin()?ops.events:[]).slice(0,6).map(e=>`<div class="row"><span class="badge">Demo</span><div class="grow"><strong>${safe(e.action)}</strong><small>${safe(e.detail)} · ${timeLabel(e.time)}</small></div></div>`).join('')||'<p class="ops-muted">Choose Next update to bring in the first event.</p>'}</section>`;bindCaseLinks()}
function nextDemoUpdate(){const n=ops.updateIndex++;const channel=assetsData.channels[n%assetsData.channels.length];if(n%4===0){ops.cases.unshift({id:'CASE-LIVE-'+Date.now(),channel:channel.id,type:'Comment',text:'Sample incoming report: standing water near Alder Street. Can municipal crews confirm the situation?',author:'Fictional resident',sentiment:'Concerned',urgency:'Critical',owner:'',status:'Open',notes:[],draft:'',created:nowISO()});logOps('New critical report · simulated','A fictional comment was added to the inbox. Requires staff verification.')}else if(n%4===1){const c=ops.cases.find(c=>c.status==='Open');if(c){c.urgency='High';logOps('Response target approaching · simulated',c.id+' now has high priority.')}}else if(n%4===2){logOps('Provider sync warning · simulated','Bluesky sample sync is delayed. No real platform was queried.')}else{ops.cases.unshift({id:'CASE-LIVE-'+Date.now(),channel:channel.id,type:'Comment',text:'Thank you for the accessible route information. It made planning our trip easier.',author:'Fictional resident',sentiment:'Positive',urgency:'Normal',owner:'',status:'Open',notes:[],draft:'',created:nowISO()});logOps('New positive comment · simulated','A fictional resident response was added to the inbox.')}saveOps();if(currentPage==='soc')renderWorkspace('soc');else if(currentPage==='inbox')renderWorkspace('inbox')}
function pauseDialog(){if(!isAdmin())return;modal(`<form id="pause-form"><div class="modal-head"><h2>${ops.paused?'Authorize publishing resume':'Pause all scheduled publishing'}</h2><button type="button" data-close aria-label="Close">×</button></div><p class="form-description">${ops.paused?'This releases the demo queue only. External transmission remains disabled.':'Every pending scheduled demo job will be blocked until an administrator resumes.'}</p><div class="field"><label for="pause-reason">Reason (required)</label><textarea id="pause-reason" required rows="3"></textarea></div><button class="btn danger" type="submit">${ops.paused?'Confirm resume':'Confirm pause'}</button></form>`);document.querySelector('#pause-form').onsubmit=e=>{e.preventDefault();const reason=document.querySelector('#pause-reason').value.trim();if(!reason)return;ops.paused=!ops.paused;logOps(ops.paused?'Emergency pause activated':'Publishing resumed',reason);close();renderWorkspace('soc')}}
function processQueue(){if(!can('content.publish'))return;if(ops.paused){toast('Blocked: emergency pause is active. No job processed.');return}const p=visiblePosts().find(p=>p.status==='Scheduled'&&(isAdmin()||hasAccountFunction(currentUser(),'content.publish','channels',p.channel)));if(!p){toast('No scheduled demo jobs.');return}p.status='Published';p.history.push({action:'Demo queue processed',time:nowISO()});logOps('Simulated publication',p.id+' processed; no external transmission.');renderWorkspace(currentPage);toast('Demo job processed. Nothing was sent to a platform.')}
function postMarkup(p){const c=channelById(p.channel);if(!c)return '';const net=c.network;return `<article class="native-post net-${net.toLowerCase()}"><header><div class="post-identity">${channelAvatar(c)}<div><strong>${safe(c.name)}</strong><small>${net==='X'||net==='Bluesky'?'@harbourview.demo':net==='LinkedIn'?'Municipal services · Fictional account':'Fictional account · Sample post'} · ${net}</small></div></div><span>•••</span></header>${net==='YouTube'?`<img class="post-media wide" src="${profileArt(p.art)}" alt="${safe(p.alt)}"><div class="post-caption"><strong>${safe(p.title)}</strong><p>${safe(p.text)}</p></div>`:net==='Instagram'?`<img class="post-media portrait" src="${profileArt(p.art)}" alt="${safe(p.alt)}"><div class="post-reactions">♡　♧　➤ <span>▢</span></div><div class="post-caption"><strong>${safe(c.name)}</strong> ${safe(p.text)}</div>`:`<div class="post-caption">${net==='LinkedIn'?'<strong>'+safe(p.title)+'</strong><br>':''}${safe(p.text)}</div><img class="post-media ${net==='X'||net==='Bluesky'?'wide':'square'}" src="${profileArt(p.art)}" alt="${safe(p.alt)}">`}<div class="post-reactions">${net==='YouTube'?'♡ Like　　Share　　Save':net==='LinkedIn'?'Like　　Comment　　Repost　　Send':net==='X'||net==='Bluesky'?'♧ Reply　　⇄ Repost　　♡ Like':'♡ Like　　♧ Comment　　➤ Share'}</div><div class="native-disclaimer">Approximate ${net} layout · fictional media · no fabricated metrics</div></article>`}
function renderContent(calendar=false){const networks=['All',...networkOptions.map(n=>n.name)];const posts=visiblePosts().filter(p=>(contentNetwork==='All'||channelById(p.channel)?.network===contentNetwork)&&(contentStatus==='All'||p.status===contentStatus)&&(p.title+' '+p.text).toLowerCase().includes(contentSearch.toLowerCase()));document.querySelector('#main').innerHTML=heading(calendar?'Publishing calendar':'All content','Review posts in a layout close to the destination channel.',can('content.create')?'<button class="btn primary" data-cmd="new-post">＋ Create content</button>':'')+`<div class="ops-filters"><label>Network<select id="content-network">${networks.map(n=>`<option ${n===contentNetwork?'selected':''}>${n}</option>`)}</select></label><label>Status<select id="content-status">${['All','Draft','In review','Approved','Scheduled','Published','Failed'].map(n=>`<option ${n===contentStatus?'selected':''}>${n}</option>`)}</select></label><label class="grow">Search<input id="content-search" placeholder="Search captions or titles…" value="${safe(contentSearch)}"></label><span class="badge">${posts.length} posts</span></div>${!isAdmin()&&!assetsData.channels.some(c=>accountAllowed(c.id))?emptyAccess():`<div class="content-wall">${posts.slice(0,contentLimit).map(p=>`<section class="content-tile"><div class="content-tile-meta"><span class="badge ${p.status==='Failed'?'fail':p.status==='Published'?'ok':'warn'}">${p.status}${ops.paused&&p.status==='Scheduled'?' · Blocked':''}</span><button class="asset-link" data-post-open="${p.id}">Open post →</button></div>${postMarkup(p)}</section>`).join('')}</div>${posts.length>contentLimit?'<button class="btn" id="load-more-content">Load more posts</button>':''}`}`;document.querySelector('#load-more-content')?.addEventListener('click',()=>{contentLimit+=18;renderContent(calendar);bindOpsCommands()});document.querySelector('#content-network').onchange=e=>{contentNetwork=e.target.value;renderContent(calendar);bindOpsCommands()};document.querySelector('#content-status').onchange=e=>{contentStatus=e.target.value;renderContent(calendar);bindOpsCommands()};document.querySelector('#content-search').oninput=e=>{contentSearch=e.target.value;const pos=e.target.selectionStart;renderContent(calendar);bindOpsCommands();const input=document.querySelector('#content-search');input.focus();input.setSelectionRange(pos,pos)};document.querySelectorAll('[data-post-open]').forEach(b=>b.onclick=()=>openPost(b.dataset.postOpen))}
function openPost(id){const p=ops.posts.find(p=>p.id===id);if(!p||!accountAllowed(p.channel))return;const editable=(isAdmin()||hasAccountFunction(currentUser(),'content.create','channels',p.channel))&&['Draft','Failed'].includes(p.status);modal(`<div class="modal-head"><h2>${safe(p.title)}</h2><button data-close aria-label="Close post">×</button></div><div class="post-dialog-grid"><div>${postMarkup(p)}</div><div><span class="badge">${p.status}</span><div class="field"><label for="post-copy">Caption</label><textarea id="post-copy" rows="7" ${editable?'':'disabled'}>${safe(p.text)}</textarea></div><div class="field"><label for="post-alt">ALT text</label><input id="post-alt" value="${safe(p.alt)}" ${editable?'':'disabled'}></div><div class="field"><label for="post-schedule">Schedule · America/Halifax</label><input id="post-schedule" type="datetime-local" value="${p.scheduled}" ${(isAdmin()||hasAccountFunction(currentUser(),'content.publish','channels',p.channel))?'':'disabled'}></div><div class="actions">${editable?'<button class="btn" id="post-save">Save draft</button><button class="btn primary" id="post-submit">Submit for review</button>':''}${(isAdmin()||hasAccountFunction(currentUser(),'content.approve','channels',p.channel))&&p.status==='In review'?'<button class="btn primary" id="post-approve">Approve</button><button class="btn" id="post-reject">Return to draft</button>':''}${(isAdmin()||hasAccountFunction(currentUser(),'content.publish','channels',p.channel))&&p.status==='Approved'?'<button class="btn primary" id="post-schedule-button">Schedule demo post</button>':''}</div><p class="ops-muted">External publication is disabled. Editing is restricted to draft or failed posts.</p><h3>History</h3>${p.history.map(h=>`<p class="ops-muted">${safe(h.action)} · ${timeLabel(h.time)}</p>`).join('')||'<p class="ops-muted">No workflow changes yet.</p>'}</div></div>`);document.querySelector('.modal-box').classList.add('wide-dialog');const transition=(status,action)=>{p.status=status;p.history.push({action,time:nowISO()});logOps(action,p.id);close();renderWorkspace('content');toast(action+' · demo only')};const saveText=()=>{p.text=document.querySelector('#post-copy').value.trim();p.alt=document.querySelector('#post-alt').value.trim();return Boolean(p.text&&p.alt)};document.querySelector('#post-save')?.addEventListener('click',()=>{if(!saveText()){toast('Caption and ALT text are required.');return}transition('Draft','Draft saved')});document.querySelector('#post-submit')?.addEventListener('click',()=>{if(!saveText()){toast('Caption and ALT text are required.');return}transition('In review','Submitted for approval')});document.querySelector('#post-approve')?.addEventListener('click',()=>transition('Approved','Human demo approval recorded'));document.querySelector('#post-reject')?.addEventListener('click',()=>transition('Draft','Returned for revision'));document.querySelector('#post-schedule-button')?.addEventListener('click',()=>{if(ops.paused){toast('Scheduling blocked while emergency pause is active.');return}const schedule=document.querySelector('#post-schedule').value;if(!schedule){toast('Choose a schedule time.');return}p.scheduled=schedule;transition('Scheduled','Scheduled in America/Halifax')})}
function newPost(){if(!can('content.create'))return;const available=assetsData.channels.filter(c=>accountAllowed(c.id));if(!available.length){toast('Assign at least one channel before creating content.');return}modal(`<form id="new-content-form"><div class="modal-head"><h2>Create content</h2><button type="button" data-close aria-label="Close">×</button></div><div class="field"><label for="new-post-channel">Channel</label><select id="new-post-channel">${available.map(c=>`<option value="${c.id}">${safe(c.name)} · ${c.network}</option>`).join('')}</select></div><div class="field"><label for="new-post-title">Title</label><input id="new-post-title" required></div><div class="field"><label for="new-post-text">Caption</label><textarea id="new-post-text" rows="5" required></textarea></div><div class="field"><label for="new-post-alt">ALT text for sample image</label><input id="new-post-alt" required value="Fictional illustration of a municipal waterfront."></div><button class="btn primary" type="submit">Save draft</button></form>`);document.querySelector('#new-content-form').onsubmit=e=>{e.preventDefault();const title=document.querySelector('#new-post-title').value.trim(),text=document.querySelector('#new-post-text').value.trim();if(!title||!text)return;const p={id:'POST-'+Date.now(),channel:document.querySelector('#new-post-channel').value,title,text,alt:document.querySelector('#new-post-alt').value,art:0,status:'Draft',scheduled:'',created:nowISO(),history:[]};ops.posts.unshift(p);logOps('Content draft created',p.id);close();renderWorkspace('content');openPost(p.id)}}
function renderInbox(){if(!can('inbox.respond'))return;const records=visibleCases().filter(c=>(inboxState==='All'||c.status===inboxState)&&(inboxType==='All'||c.type===inboxType)&&(inboxSentiment==='All'||c.sentiment===inboxSentiment)&&(inboxOwner==='All'||(inboxOwner==='Unassigned'?!c.owner:c.owner===inboxOwner))&&(c.text+' '+c.id).toLowerCase().includes(inboxSearch.toLowerCase()));if(!records.some(c=>c.id===selectedCase))selectedCase=records[0]?.id;const c=records.find(c=>c.id===selectedCase);document.querySelector('#main').innerHTML=heading('Resident inbox & comments','Sentiment is a derived signal. A named staff member owns the response.')+`<div class="ops-filters"><label>Type<select id="inbox-type">${['All','Comment','Message'].map(n=>`<option ${n===inboxType?'selected':''}>${n}</option>`)}</select></label><label>Sentiment<select id="inbox-sentiment">${['All','Negative','Concerned','Neutral','Positive'].map(n=>`<option ${n===inboxSentiment?'selected':''}>${n}</option>`)}</select></label><label>Owner<select id="inbox-owner"><option>All</option><option ${inboxOwner==='Unassigned'?'selected':''}>Unassigned</option>${accessUsers.map(u=>`<option value="${u.id}" ${inboxOwner===u.id?'selected':''}>${safe(u.name)}</option>`).join('')}</select></label><label>Status<select id="inbox-state">${['Open','Resolved','All'].map(n=>`<option ${n===inboxState?'selected':''}>${n}</option>`)}</select></label><label>Search<input id="inbox-search" value="${safe(inboxSearch)}" placeholder="Case or message…"></label></div>${!isAdmin()&&!assetsData.channels.some(c=>accountAllowed(c.id))?emptyAccess():`<div class="inbox-workspace"><section class="case-list"><div class="case-count">${records.length} conversations</div>${records.map(x=>`<button class="case-item ${x.id===selectedCase?'selected':''}" data-select-case="${x.id}"><span class="case-top"><strong>${x.id}</strong><span class="badge ${x.urgency==='Critical'?'fail':'warn'}">${x.urgency}</span></span><p>${safe(x.text.slice(0,110))}</p><small>${channelById(x.channel)?.network} · ${x.type} · ${x.sentiment}</small><small>Owner: ${safe(accessUsers.find(u=>u.id===x.owner)?.name||'Unassigned')}</small></button>`).join('')||'<p class="ops-muted">No conversations match.</p>'}</section><section class="case-detail">${c?caseDetailMarkup(c):'<div class="ops-empty">Select a conversation.</div>'}</section></div>`}`;const setters={'inbox-type':v=>inboxType=v,'inbox-sentiment':v=>inboxSentiment=v,'inbox-owner':v=>inboxOwner=v,'inbox-state':v=>inboxState=v};Object.entries(setters).forEach(([id,set])=>document.querySelector('#'+id).onchange=e=>{set(e.target.value);renderInbox()});document.querySelector('#inbox-search').oninput=e=>{inboxSearch=e.target.value;const pos=e.target.selectionStart;renderInbox();const i=document.querySelector('#inbox-search');i.focus();i.setSelectionRange(pos,pos)};document.querySelectorAll('[data-select-case]').forEach(b=>b.onclick=()=>{selectedCase=b.dataset.selectCase;renderInbox()});if(c)bindCaseActions(c)}
function caseDetailMarkup(c){const channel=channelById(c.channel);return `<div class="case-detail-header">${channelAvatar(channel)}<div><h3>${c.id} · ${c.type}</h3><p>${safe(channel.name)} · ${c.status}</p></div></div><div class="resident-message"><strong>${safe(c.author)}</strong><p>${safe(c.text)}</p><small>Fictional conversation · ${timeLabel(c.created)}</small></div><div class="case-fields"><label>Sentiment (staff override)<select id="case-sentiment">${['Negative','Concerned','Neutral','Positive'].map(s=>`<option ${s===c.sentiment?'selected':''}>${s}</option>`)}</select></label><label>Priority<select id="case-priority">${['Normal','High','Critical'].map(s=>`<option ${s===c.urgency?'selected':''}>${s}</option>`)}</select></label><label>Response owner<select id="case-owner"><option value="">Unassigned</option>${accessUsers.filter(u=>hasAccountFunction(u,'inbox.respond','channels',c.channel)||u.id===c.owner).map(u=>`<option value="${u.id}" ${u.id===c.owner?'selected':''}>${safe(u.name)}${hasAccountFunction(u,'inbox.respond','channels',c.channel)?'':' · needs account permission'}</option>`).join('')}</select></label></div><p class="ops-muted">Sentiment: simulated model signal, uncertain. Staff can override. Critical reports require verification.</p><button class="btn" id="save-case-routing">Save assignment & classification</button><h3>Internal notes</h3>${c.notes.map(n=>`<div class="internal-note"><strong>${safe(n.author)}</strong><p>${safe(n.text)}</p><small>${timeLabel(n.time)}</small></div>`).join('')}<div class="field"><label for="case-note">New internal note</label><textarea id="case-note" rows="2" placeholder="Only staff can see this note"></textarea></div><button class="btn" id="save-case-note">Save internal note</button><h3 style="margin-top:25px">Reply draft</h3><div class="field"><label for="case-reply">Human-reviewed response</label><textarea id="case-reply" rows="4">${safe(c.draft)}</textarea></div><div class="actions"><button class="btn" id="suggest-case-reply">Mock AI suggestion</button><button class="btn" id="save-case-reply">Save draft</button><button class="btn primary" id="resolve-case">${c.status==='Resolved'?'Reopen case':'Review & resolve'}</button></div><p class="ops-muted">Mock suggestions are not verified advice. No external reply is sent. Replies require a response owner.</p>`}
function bindCaseActions(c){document.querySelector('#save-case-routing').onclick=()=>{c.owner=document.querySelector('#case-owner').value;c.sentiment=document.querySelector('#case-sentiment').value;c.urgency=document.querySelector('#case-priority').value;logOps('Case assignment/classification saved',c.id);renderInbox();toast('Owner, sentiment and priority saved.')};document.querySelector('#save-case-note').onclick=()=>{const text=document.querySelector('#case-note').value.trim();if(!text){toast('Enter an internal note.');return}c.notes.push({text,time:nowISO(),author:isAdmin()?'Demo administrator':currentUser().name});logOps('Internal note added',c.id);renderInbox()};document.querySelector('#suggest-case-reply').onclick=()=>{document.querySelector('#case-reply').value='Thank you for letting us know. Our team is reviewing this report and will share a confirmed update when available. For immediate danger, use the appropriate emergency service. [Mock draft — verify before use]';toast('Mock suggestion inserted. Edit and review before saving.')};document.querySelector('#save-case-reply').onclick=()=>{c.draft=document.querySelector('#case-reply').value;logOps('Reply draft saved',c.id);toast('Draft saved. Nothing sent.')};document.querySelector('#resolve-case').onclick=()=>{if(c.status==='Resolved'){c.status='Open';logOps('Case reopened',c.id);renderInbox();return}if(!c.owner){toast('Assign a response owner first, then save the assignment.');return}if(!hasAccountFunction(accessUsers.find(u=>u.id===c.owner),'inbox.respond','channels',c.channel)){toast('The response owner needs inbox permission and explicit access to this channel. Update Users & access first.');return}c.draft=document.querySelector('#case-reply').value.trim();if(!c.draft){toast('Write or save a reply draft before review.');return}modal(`<div class="modal-head"><h2>Review & resolve ${c.id}</h2><button data-close aria-label="Close">×</button></div><p class="form-description">Response owner: ${safe(accessUsers.find(u=>u.id===c.owner)?.name)}</p><blockquote class="resident-message">${safe(c.draft)}</blockquote><p class="ops-muted">This resolves the demo case only. It sends no message to a social network.</p><button class="btn primary" id="confirm-case-resolution">Confirm demo resolution</button>`);document.querySelector('#confirm-case-resolution').onclick=()=>{c.status='Resolved';logOps('Case resolved after human review',c.id);close();renderInbox();toast('Demo case resolved. No external reply sent.')}}}
function bindCaseLinks(){document.querySelectorAll('[data-case-open]').forEach(b=>b.onclick=()=>{if(!can('inbox.respond')){toast('Inbox function permission required.');return}selectedCase=b.dataset.caseOpen;inboxState='Open';inboxType='All';inboxSentiment='All';inboxOwner='All';inboxSearch='';renderWorkspace('inbox')})}
function renderPreferences(){const p=getPreferences();document.querySelector('#main').innerHTML=heading('My preferences','Display and accessibility settings apply only to the current demo user.')+`<form id="preferences-form" class="card preferences-card"><h3>Appearance</h3><div class="field"><label for="pref-theme">Theme</label><select id="pref-theme"><option value="dark" ${p.theme==='dark'?'selected':''}>Dark</option><option value="light" ${p.theme==='light'?'selected':''}>Light</option></select></div><h3>Accessibility / AODA support preferences</h3><p class="ops-muted">Personal display adjustments. These controls do not establish AODA compliance.</p><div class="field"><label for="pref-size">Text size</label><select id="pref-size">${['standard','large','extra-large'].map(s=>`<option value="${s}" ${p.size===s?'selected':''}>${s.replace('-',' ')}</option>`)}</select></div>${[['contrast','Higher contrast'],['motion','Reduce motion and pause demo stream'],['focus','Stronger keyboard focus indicator']].map(([id,label])=>`<label class="preference-toggle"><input id="pref-${id}" type="checkbox" ${p[id]?'checked':''}>${label}</label>`).join('')}<button type="submit" class="btn primary">Save my preferences</button><p class="ops-muted">Saved separately for ${isAdmin()?'Demo administrator':safe(currentUser().name)}. No workspace-wide accessibility configuration.</p></form>`;document.querySelector('#preferences-form').onsubmit=e=>{e.preventDefault();const settings={theme:document.querySelector('#pref-theme').value,size:document.querySelector('#pref-size').value,contrast:document.querySelector('#pref-contrast').checked,motion:document.querySelector('#pref-motion').checked,focus:document.querySelector('#pref-focus').checked};localStorage.setItem(preferenceKey(),JSON.stringify(settings));if(settings.motion&&streamTimer){clearInterval(streamTimer);streamTimer=null}applyPreferences();toast('Your personal preferences were saved.')}}
function renderAudit(){document.querySelector('#main').innerHTML=heading('Activity log','Browser-local demonstration audit. Production immutability is not implemented.')+`<section class="card">${ops.events.map(e=>`<div class="row"><div class="grow"><strong>${safe(e.action)}</strong><small>${safe(e.detail)} · ${safe(e.actor||'Demo')} · ${timeLabel(e.time)}</small></div></div>`).join('')||'<p>No events yet.</p>'}</section>`}
function renderSupporting(page){document.querySelector('#main').innerHTML=heading(page==='ads'?'Advertising':'Insights preview','This module is planned. No external service is connected.')+'<section class="card"><h3>Next implementation step</h3><p class="ops-muted">Use the implemented content, SOC, inbox, asset-group and user-management workflows. Paid purchasing remains disabled.</p></section>'}
function bindOpsCommands(){document.querySelectorAll('[data-cmd]').forEach(b=>{const cmd=b.dataset.cmd;if(cmd==='menu')return;b.onclick=()=>{if(['stream','next-update'].includes(cmd)&&!isAdmin()){toast('Only the demo administrator controls the simulation.');return}if(cmd==='next-update')nextDemoUpdate();if(cmd==='stream'){if(streamTimer){clearInterval(streamTimer);streamTimer=null}else if(getPreferences().motion){toast('Reduced motion is enabled. Use Next update instead.');return}else streamTimer=setInterval(nextDemoUpdate,12000);renderWorkspace('soc')}if(cmd==='pause-publishing')pauseDialog();if(cmd==='process-queue')processQueue();if(cmd==='new-post')newPost();if(cmd==='critical-case'){const c=visibleCases().find(c=>c.status==='Open'&&c.urgency==='Critical');if(c){selectedCase=c.id;renderWorkspace('inbox')}else toast('No open critical case.')}}})}
// Brand hierarchy: master rules are compiled first, inherited read-only, never replaced by sub-guidelines.
function brandBoard(){const id=assetsData.selected,g=assetsData.groups.find(g=>g.id===id);if(!ops.boards[id])ops.boards[id]={master:{name:g.brand,voice:g.voice,mood:'Calm, helpful and confident',tone:'Plain-language, respectful and inclusive',dos:'Use verified service facts.\nUse accessible language and ALT text.\nInclude clear next steps and approved sources.',donts:'Do not disclose resident personal information.\nDo not invent service facts or emergency guidance.\nDo not publish without human review.',logo:profileArt(assetsData.groups.indexOf(g)%6),colors:g.color+' #151813 #F4F7EE',font:'Inter / system sans-serif'},sets:[{id:'everyday',name:'Everyday service updates',purpose:g.direction,voice:'Practical and concise',dos:'Lead with the service change and effective date.',donts:'Avoid jargon and unexplained acronyms.',reviewed:true},{id:'community',name:'Community & recreation',purpose:'Encourage inclusive participation in programs, trails and community events.',voice:'Warm and welcoming',dos:'Include accessibility and fee-assistance information when verified.',donts:'Avoid exclusionary language or unsupported availability claims.',reviewed:true}],selected:'everyday',refs:[]};return ops.boards[id]}
function compiledBrand(board,set){return {mode:'LOCAL PROMPT PREVIEW — no AI call',precedence:['Master asset-group guardrails (mandatory)','Selected guideline additions (cannot override master)'],master:board.master,guideline:{...set,logo:undefined},visualReferences:commonSizes.map(([label,width,height])=>({label,width,height,status:'Generic working canvas; destination requirements unverified',samples:['Service notice','Community story','Event announcement']})),humanReviewRequired:true,externalPublishing:false}}
function decorateBrand(){if(currentPage!=='assets'||assetTab!=='brand')return;const board=brandBoard(),set=board.sets.find(s=>s.id===board.selected)||board.sets[0];document.querySelector('.asset-body').innerHTML=`<div class="brand-master-banner"><strong>Master direction governs every guideline</strong><p>Sub-guidelines can add detail. They cannot remove or replace these do’s and don’ts.</p></div><div class="brand-editor-tabs"><button data-brand-mode="master">Master guardrails & identity</button><button data-brand-mode="sets">Guideline sets (${board.sets.length})</button><button data-brand-mode="visuals">Visual reference library</button><button data-brand-mode="prompt">AI brief preview</button></div><div id="brand-editor-content"></div>`;document.querySelectorAll('[data-brand-mode]').forEach(b=>b.onclick=()=>renderBrandMode(b.dataset.brandMode));renderBrandMode('master')}
function renderBrandMode(mode){const board=brandBoard(),master=board.master,set=board.sets.find(s=>s.id===board.selected)||board.sets[0];document.querySelectorAll('[data-brand-mode]').forEach(b=>b.classList.toggle('active',b.dataset.brandMode===mode));const target=document.querySelector('#brand-editor-content');if(mode==='master'){target.innerHTML=`<form id="master-brand-form"><h3>Master identity & non-negotiable guardrails</h3><div class="brand-logo-row"><img src="${master.logo}" alt="Saved brand logo or sample mark"><div><label for="brand-logo-file">Upload logo · PNG, JPEG or WebP, max 600 KB</label><input id="brand-logo-file" type="file" accept="image/png,image/jpeg,image/webp"><p class="ops-muted">Stored in this browser demo only. No upload to an external service.</p></div></div>${[['name','Brand name'],['colors','Brand colours (hex codes)'],['font','Typography'],['voice','Voice'],['mood','Mood'],['tone','Tone']].map(([key,label])=>`<div class="field"><label for="master-${key}">${label}</label><input id="master-${key}" value="${safe(master[key]||'')}"></div>`).join('')}<div class="ops-columns">${[['dos','Master DO'],['donts','Master DON’T']].map(([key,label])=>`<div class="field"><label for="master-${key}">${label} · inherited by every set</label><textarea id="master-${key}" rows="6" required>${safe(master[key])}</textarea></div>`).join('')}</div><button class="btn primary" type="submit">Save master direction</button></form>`;let pendingLogo=master.logo;document.querySelector('#brand-logo-file').onchange=e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>600*1024){toast('Choose a PNG, JPEG or WebP under 600 KB.');e.target.value='';return}const reader=new FileReader();reader.onload=()=>{pendingLogo=reader.result;target.querySelector('.brand-logo-row img').src=pendingLogo};reader.readAsDataURL(file)};document.querySelector('#master-brand-form').onsubmit=e=>{e.preventDefault();for(const key of ['name','colors','font','voice','mood','tone','dos','donts'])master[key]=document.querySelector('#master-'+key).value.trim();master.logo=pendingLogo;board.sets.forEach(s=>s.reviewed=false);logOps('Master brand direction updated','All guideline sets require renewed review.');toast('Master saved. Review each guideline against the updated rules.')}}else if(mode==='sets'){target.innerHTML=`<div class="asset-section-title"><div><h3>Guideline sets</h3><p>One master direction. Multiple campaign and service briefs.</p></div><button class="btn primary" id="add-guideline">＋ Add guideline</button></div><div class="guideline-selector">${board.sets.map(s=>`<button data-guideline="${s.id}" class="${s.id===set.id?'selected':''}">${safe(s.name)} <span class="badge ${s.reviewed?'ok':'warn'}">${s.reviewed?'Reviewed':'Needs review'}</span></button>`).join('')}</div><div class="inherited-rules"><strong>Inherited master rules · read-only</strong><p><b>DO:</b> ${safe(master.dos).replace(/\n/g,'<br>')}</p><p><b>DON’T:</b> ${safe(master.donts).replace(/\n/g,'<br>')}</p></div><form id="guideline-form">${[['name','Guideline name'],['purpose','Goals, audience & content direction'],['voice','Additional voice guidance'],['dos','Additional DO'],['donts','Additional DON’T']].map(([key,label])=>`<div class="field"><label for="set-${key}">${label}</label><textarea id="set-${key}" rows="${key==='purpose'?3:2}" ${key==='name'?'required':''}>${safe(set[key]||'')}</textarea></div>`).join('')}<label class="preference-toggle"><input type="checkbox" id="guideline-reviewed" ${set.reviewed?'checked':''}>I reviewed this set against all master guardrails.</label><p class="ops-muted">Human review is required. The demo does not claim to detect every semantic conflict.</p><button class="btn primary" type="submit">Save guideline</button></form>`;document.querySelectorAll('[data-guideline]').forEach(b=>b.onclick=()=>{board.selected=b.dataset.guideline;saveOps();renderBrandMode('sets')});document.querySelector('#add-guideline').onclick=()=>{const s={id:crypto.randomUUID(),name:'New guideline '+(board.sets.length+1),purpose:'',voice:'',dos:'',donts:'',reviewed:false};board.sets.push(s);board.selected=s.id;saveOps();renderBrandMode('sets')};document.querySelector('#guideline-form').onsubmit=e=>{e.preventDefault();for(const key of ['name','purpose','voice','dos','donts'])set[key]=document.querySelector('#set-'+key).value.trim();set.reviewed=document.querySelector('#guideline-reviewed').checked;logOps('Guideline saved',set.name+'; master rules retained.');toast('Guideline saved with inherited master guardrails.')}}else if(mode==='visuals'){target.innerHTML=`<h3>Visual references by working canvas</h3><p class="ops-muted">Three fictional examples per format. These are reusable aspect-ratio references, not verified platform upload limits or crop guarantees.</p><div class="reference-grid">${commonSizes.map(([label,w,h],i)=>`<section class="reference-format"><h4>${label} <small>${w} × ${h} · ${(w/h).toFixed(2)} ratio</small></h4><div class="reference-samples">${[0,1,2].map(j=>`<button data-reference="${i}-${j}" aria-label="Open ${label} sample ${j+1}"><img src="${profileArt((i+j)%6)}" style="aspect-ratio:${w}/${h}" alt="Fictional ${['service notice','community story','event announcement'][j]} layout reference"><small>${['Service notice','Community story','Event announcement'][j]}</small></button>`).join('')}</div></section>`).join('')}</div>`;document.querySelectorAll('[data-reference]').forEach(b=>b.onclick=()=>{const [i,j]=b.dataset.reference.split('-').map(Number),[label,w,h]=commonSizes[i];modal(`<div class="modal-head"><h2>${label} · sample ${j+1}</h2><button data-close aria-label="Close">×</button></div><img class="reference-large" style="aspect-ratio:${w}/${h}" src="${profileArt((i+j)%6)}" alt="Fictional visual layout reference"><p class="ops-muted">${w} × ${h}. Keep essential text within safe margins. Verify platform-specific cropping before publishing.</p>`)});}else{const prompt=compiledBrand(board,set);target.innerHTML=`<h3>Combined AI brief</h3><div class="field"><label for="prompt-guideline">Guideline set</label><select id="prompt-guideline">${board.sets.map(s=>`<option value="${s.id}" ${s.id===set.id?'selected':''}>${safe(s.name)}</option>`).join('')}</select></div><p class="ops-muted">Master guardrails are always included first. No model receives this preview. Unreviewed sets cannot be exported.</p><pre class="prompt-preview">${safe(JSON.stringify(prompt,null,2))}</pre><button class="btn primary" id="download-brand-brief" ${set.reviewed?'':'disabled'}>Download reviewed brief</button>${set.reviewed?'':'<p class="ops-muted">Review this guideline against the master direction first.</p>'}`;document.querySelector('#prompt-guideline').onchange=e=>{board.selected=e.target.value;saveOps();renderBrandMode('prompt')};document.querySelector('#download-brand-brief').onclick=()=>{if(!set.reviewed)return;const blob=new Blob([JSON.stringify(prompt,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='SAMPLE-brand-brief.json';a.click();URL.revokeObjectURL(url);toast('Reviewed local brief downloaded. No AI call made.')}}}
const assetsBeforeBrand=showAssetGroups;showAssetGroups=function(){assetsBeforeBrand();decorateBrand()};
// Stop the older global handlers from handling navigation IDs in this workspace shell.
document.addEventListener('click',e=>{const destination=e.target.closest('[data-go]');if(destination){e.preventDefault();e.stopImmediatePropagation();renderWorkspace(destination.dataset.go)}},true);
renderWorkspace('soc');
